package autonewsroller.tts;

import autonewsroller.util.Json;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class KokoroNarrator implements NarrationEngine {private final Path root;public KokoroNarrator(Path root){this.root=root;}public String name(){return "Kokoro";}public NarrationResult narrate(String text,String voice,Path output)throws Exception{Files.createDirectories(output.getParent());Path txt=output.resolveSibling(output.getFileName()+".txt");Files.writeString(txt,text,StandardCharsets.UTF_8);String py=Files.isRegularFile(root.resolve(".venv-kokoro/Scripts/python.exe"))?root.resolve(".venv-kokoro/Scripts/python.exe").toString():"python";ProcessBuilder b=new ProcessBuilder(py,root.resolve("tools/kokoro_tts.py").toString(),"--text-file",txt.toString(),"--output",output.toString(),"--voice",voice);ProcessRunner.run(b,300);if(!Files.isRegularFile(output)||Files.size(output)==0)throw new IllegalStateException("Kokoro did not create WAV");Path meta=output.resolveSibling(output.getFileName()+".json");Map<String,Object>m=new LinkedHashMap<>();m.put("engine","Kokoro");m.put("voice",voice);m.put("wav",output.toString());Json.write(meta,m);System.out.println("TTS engine used: Kokoro");return new NarrationResult("Kokoro",voice,output,meta);}}
